const ticket = $('✅ Validar & Formatear').first().json;
const aiRaw = $input.first().json;

let classification;
try {
  const content = aiRaw.choices[0].message.content;
  classification = JSON.parse(content);
} catch(e) {
  classification = {
    category: 'otro',
    confidence: 0.3,
    suggested_response: 'Recibimos tu consulta. Un agente te contactará pronto.',
    is_sensitive: true,
    reasoning: 'Error parsing IA — fallback activado'
  };
}

const needsHITL = classification.confidence < 0.7 
  || classification.category === 'devolucion'
  || classification.category === 'pago';

const hitlReason = classification.confidence < 0.7 
  ? `Confianza baja (${(classification.confidence * 100).toFixed(0)}%)`
  : classification.is_sensitive 
    ? 'Tema sensible'
    : 'Categoría devolución';

return [{
  json: {
    ...ticket,
    category: classification.category,
    confidence: classification.confidence,
    suggested_response: classification.suggested_response,
    is_sensitive: classification.is_sensitive,
    reasoning: classification.reasoning,
    needs_hitl: needsHITL,
    hitl_reason: needsHITL ? hitlReason : null,
    classified_at: new Date().toISOString()
  }
}];

const data = $input.first().json;

return [{
  json: {
    ...data,
    decision: 'auto',
    response_to_send: data.suggested_response,
    decided_at: new Date().toISOString()
  }
}];

const original = $('📋 Parsear Clasificación').first().json;
const hitlResponse = $input.first().json;

let finalResponse = original.suggested_response;
let decision = hitlResponse.action;

if (decision === 'edit' && hitlResponse.comments) {
  finalResponse = hitlResponse.comments;
} else if (decision === 'reject') {
  finalResponse = null;
}

return [{
  json: {
    ...original,
    decision: `hitl_${decision}`,
    response_to_send: finalResponse,
    decided_at: new Date().toISOString()
  }
}];

