const data = $input.first().json;
const receivedAt = new Date(data.received_at);
const now = new Date();
const latencyMs = now - receivedAt;

return [{
  json: {
    ticket_id: data.ticket_id,
    customer: data.customer,
    category: data.category,
    confidence: data.confidence,
    decision: data.decision,
    hitl_reason: data.hitl_reason || null,
    response_sent: !!data.response_to_send,
    escalated_to: data.escalated_to || null,
    latency_ms: latencyMs,
    received_at: data.received_at,
    completed_at: now.toISOString()
  }
}];

const data = $input.first().json;
const response = data.suggested_response || '';
const category = data.category || '';

// Regla 1: Largo mínimo
const largoMinimo = response.length > 30;

// Regla 2: Sin promesas falsas
const promesasFalsas = /inmediatamente|al instante|ya mismo/i.test(response);
const sinPromesasFalsas = !promesasFalsas;

// Regla 3: Tono empático
const tonoEmpatico = /hola|lamento|disculp|sentimos/i.test(response);

// Regla 4: Categoría válida
const categoriasValidas = ['envio', 'pago', 'devolucion', 'tecnico', 'facturacion', 'otro'];
const categoriaValida = categoriasValidas.includes(category);

// Regla 5: Sin datos sensibles (DNI o tarjeta)
const dniPattern = /\b\d{7,8}\b/;
const tarjetaPattern = /\b\d{4}[\s-]?\d{4}[\s-]?\d{4}[\s-]?\d{4}\b/;
const sinDatosSensibles = !dniPattern.test(response) && !tarjetaPattern.test(response);

// Calcular score
const details = [
  { rule: 'largo_minimo', passed: largoMinimo, description: 'Más de 30 caracteres' },
  { rule: 'sin_promesas_falsas', passed: sinPromesasFalsas, description: 'No contiene promesas inmediatas' },
  { rule: 'tono_empatico', passed: tonoEmpatico, description: 'Contiene palabras empáticas' },
  { rule: 'categoria_valida', passed: categoriaValida, description: 'Categoría válida' },
  { rule: 'sin_datos_sensibles', passed: sinDatosSensibles, description: 'No contiene DNI o tarjeta' }
];

const score = details.filter(d => d.passed).length;
const total = details.length;
const pct = (score / total) * 100;
const passed = score >= 4;

return [{
  json: {
    ...data,
    eval_rules: {
      score,
      total,
      pct: Math.round(pct),
      passed,
      details
    }
  }
}];

