const data = $('📏 Eval Rules').first().json;
const llmRaw = $input.first().json;

let llmEval;
try {
  const content = llmRaw.choices[0].message.content;
  llmEval = JSON.parse(content);
} catch(e) {
  // Fallback si el LLM falló
  llmEval = {
    scores: { relevancia: 0, empatia: 0, claridad: 0, seguridad: 0 },
    score_total: 0,
    aprobado: false,
    razon: 'Error parsing respuesta LLM'
  };
}

const rulesPass = data.eval_rules.passed;
const llmPass = llmEval.aprobado;

let decision;
let needsHitl = data.needs_hitl;
let hitlReason = data.hitl_reason;

if (rulesPass && llmPass) {
  decision = 'aprobado';
} else if (rulesPass && !llmPass) {
  decision = 'aprobado_con_advertencia';
} else if (!rulesPass) {
  decision = 'rechazado_rules';
  needsHitl = true;
  hitlReason = `Eval rules falló: ${data.eval_rules.score}/${data.eval_rules.total} reglas pasadas`;
} else if (!llmPass) {
  decision = 'rechazado_llm';
  needsHitl = true;
  hitlReason = `Eval LLM rechazó: ${llmEval.razon}`;
}

return [{
  json: {
    ...data,
    eval_llm: llmEval,
    eval_decision: decision,
    needs_hitl: needsHitl,
    hitl_reason: hitlReason
  }
}];
